import type { Database } from '@database/client.database'
import { migrate } from 'drizzle-orm/pglite/migrator'

/** Applies the pending SQL migrations generated by `drizzle-kit generate`. */
export async function migrateDatabase(database: Database, migrationsFolder: string): Promise<void> {
  const failure = await migrate(database, { migrationsFolder })

  if (failure) {
    throw new Error(`Database migration failed: ${JSON.stringify(failure)}`)
  }
}
